//! 📚️ A completed replay prepares its cursor and revision metadata without changing visible history.
use crate::{CursorRevisionAccumulator,CursorRevisionRecord,native_digest::{NativeEditDigest,NativeEffectiveDigest,with_operation_identity}};
use semio_framework_os_spr::{Edit,Mutation,MutationId};
use semio_framework_os_vcs::{ArtifactHistoryKey,HistoryPageStack};
use semio_framework_value::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,ValueError,ValueRefusalKind};
use semio_framework_value_persistent::list::PagedList;
use std::mem::{ManuallyDrop,size_of};
use protocol::HistoryFoldIndex;
use semio_framework_value::retained_clone::RetainedCloneClose;
/// 🪪️ These pure codec borrows remain protected by the enclosing publisher's actual original history read.
pub struct ReplayMetadataRow<'a,M>{pub ledger_key:ArtifactHistoryKey,pub edit:&'a Edit<M>,pub inverse:&'a PagedList<M,{usize::MAX}>,pub supersessions:&'a crate::lifted_replay::EffectiveSupersessions,pub flags:&'a HistoryFoldIndex<([u8;32],usize),bool>,pub previous_flags:&'a HistoryFoldIndex<([u8;32],usize),bool>}
/// 🧳️ Private metadata and its close cursor retain every admitted backing until transfer or retirement.
pub struct OriginalReplayMetadata{revision:ManuallyDrop<Option<CursorRevisionAccumulator>>,cursor:ManuallyDrop<Option<HistoryPageStack<String>>>,retirement:RetainedCloneClose,digest:NativeEditDigest,effective:NativeEffectiveDigest,source:Option<(ArtifactHistoryKey,usize)>,ordinal:usize,redo_ordinal:usize,operation:usize,phase:u8,finished:bool,closing:bool}
fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn permits(grant:RetainedCloneGrant,d:RetirementDemand)->bool{semio_framework_value::retained_clone::retained_clone_grant_admits(grant,d)}
fn p(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl OriginalReplayMetadata{
 /// 🌱️ Retains empty destinations and the original document identity digest without scanning history.
 pub fn new(identity_digest:[u8;32])->Self{Self{revision:ManuallyDrop::new(Some(CursorRevisionAccumulator{identity_digest,applied:HistoryPageStack::empty(),redo:HistoryPageStack::empty(),applied_tail_chains:None,mutation_positions:Default::default(),indexed_edits:Default::default(),unit_flags:Default::default()})),cursor:ManuallyDrop::new(Some(HistoryPageStack::empty())),retirement:Default::default(),digest:Default::default(),effective:Default::default(),source:None,ordinal:0,redo_ordinal:0,operation:0,phase:0,finished:false,closing:false}}
 /// 📍️ Selects the next original edit whose enclosing source must remain retained throughout this row.
 pub fn ordinal(&self)->usize{self.ordinal}
 /// 🏁️ Readiness grants no visibility; publication still owns its original common decision.
 pub fn prepared(&self)->bool{self.finished&&!self.closing}
 /// 🪡️ Advances one actual original metadata action and returns its exact ownership receipt.
 pub fn advance<P,M:Mutation<P>>(&mut self,row:Option<ReplayMetadataRow<'_,M>>,redo:&HistoryPageStack<CursorRevisionRecord>,grant:RetainedCloneGrant,mut digest:impl FnMut(&mut NativeEditDigest,&Edit<M>,&PagedList<M,{usize::MAX}>,RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>,mut admit:impl FnMut(usize)->Result<(),ValueError>)->Result<RetainedCloneProgress,ValueError>{
  if grant.maximum_items==0||grant.maximum_copy_bytes==0||grant.maximum_depth==0{return Ok(Default::default())}if self.closing{return Err(invalid("closing replay metadata cannot resume preparation"))}if self.finished{return Ok(Default::default())}let Some(row)=row else{if self.redo_ordinal<redo.len(){let target=&mut self.revision.as_mut().unwrap().redo;let d=RetirementDemand{copy_bytes:size_of::<CursorRevisionRecord>()+size_of::<usize>(),capacity_bytes:target.next_push_allocation_bytes(),depth:1,..Default::default()};if !permits(grant,d){return Ok(Default::default())}admit(d.capacity_bytes)?;target.try_push(redo[self.redo_ordinal].clone()).map_err(|_|invalid("admitted replay redo backing refused its original row"))?;self.redo_ordinal+=1;return Ok(p(d))}let d=RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()};if !permits(grant,d){return Ok(Default::default())}if self.source.is_some(){return Err(invalid("replay metadata lost its original active edit"))}self.finished=true;return Ok(p(d))};let address=row.edit as*const _ as usize;if self.source.is_some_and(|source|source!=(row.ledger_key,address)){return Err(invalid("replay metadata changed its original edit loan"))}
  if self.phase==0{let receipt=digest(&mut self.digest,row.edit,row.inverse,grant)?;if receipt.copied_items!=0{self.source=Some((row.ledger_key,address));}if self.digest.digest().is_some(){self.phase=1;}return Ok(receipt)}
  if self.phase==1{let receipt=self.effective.advance::<P,M>(row.edit,row.supersessions,self.digest.digest().unwrap(),grant)?;if self.effective.digest().is_some(){self.phase=2;}return Ok(receipt)}
  let id_digest=CursorRevisionAccumulator::hash_record(b"edit-id",&[row.edit.id.as_bytes()]);
  macro_rules! index_slot{($index:expr,$key:expr)=>{{let index=&mut $index;let key=$key;let capacity=index.next_insert_capacity_byte_demand(key,grant.maximum_copy_bytes)?;let d=RetirementDemand{capacity_bytes:capacity,depth:index.next_insert_depth_demand(key)?,..Default::default()};if !permits(grant,d){return Ok(Default::default())}if capacity!=0{admit(capacity)?;return index.reserve_insert_step(key,grant).map_err(|(error,receipt)|error.with_retained_progress(receipt))}}}}
  match self.phase{
   2=>{let target=self.cursor.as_mut().unwrap();let bytes=row.edit.id.len();let d=RetirementDemand{copy_bytes:bytes+size_of::<String>(),capacity_bytes:target.next_push_allocation_bytes()+bytes,depth:1,..Default::default()};if !permits(grant,d){return Ok(Default::default())}admit(d.capacity_bytes)?;target.try_push(row.edit.id.clone()).map_err(|_|invalid("admitted replay cursor backing refused its original row"))?;self.phase=3;Ok(p(d))},
   3=>{let revision=self.revision.as_mut().unwrap();let d=RetirementDemand{copy_bytes:size_of::<CursorRevisionRecord>()+64,capacity_bytes:revision.applied.next_push_allocation_bytes(),depth:1,..Default::default()};if !permits(grant,d){return Ok(Default::default())}admit(d.capacity_bytes)?;let effective=self.effective.digest().unwrap();let previous=revision.applied.last().map_or(revision.identity_digest,|value|value.prefix_digest);revision.applied.try_push(CursorRevisionRecord::new(Some(row.ledger_key),id_digest,effective,CursorRevisionAccumulator::hash_record(b"applied",&[&previous,&effective]))).map_err(|_|invalid("admitted replay revision backing refused its original row"))?;self.phase=4;Ok(p(d))},
   4=>{let revision=self.revision.as_mut().unwrap();index_slot!(revision.indexed_edits,&id_digest);let d=RetirementDemand{copy_bytes:32+2*size_of::<usize>(),depth:revision.indexed_edits.next_insert_depth_demand(&id_digest)?,..Default::default()};if !permits(grant,d){return Ok(Default::default())}revision.indexed_edits.insert_reserved(id_digest,(self.ordinal,row.edit.forwards.len()),grant).map_err(|(error,_,_)|error)?;self.phase=5;Ok(p(d))},
   5 if self.operation<row.edit.forwards.len()=>{with_operation_identity::<P,M,_>(row.edit,self.operation,|id|{let revision=self.revision.as_mut().unwrap();index_slot!(revision.mutation_positions,id);let d=RetirementDemand{copy_bytes:id.len()+size_of::<(MutationId,(usize,usize,[u8;32]))>(),capacity_bytes:id.len(),depth:revision.mutation_positions.next_insert_depth_demand(id)?,..Default::default()};if !permits(grant,d){return Ok(Default::default())}admit(d.capacity_bytes)?;revision.mutation_positions.insert_reserved(MutationId(id.to_owned()),(self.ordinal,self.operation,id_digest),grant).map_err(|(error,_,_)|error)?;self.phase=6;Ok(p(d))})},
   6=>{let key=(id_digest,self.operation);if let Some(flag)=row.flags.get(&key).or_else(||row.previous_flags.get(&key)){let revision=self.revision.as_mut().unwrap();index_slot!(revision.unit_flags,&key);let d=RetirementDemand{copy_bytes:size_of::<(([u8;32],usize),bool)>(),depth:revision.unit_flags.next_insert_depth_demand(&key)?,..Default::default()};if !permits(grant,d){return Ok(Default::default())}revision.unit_flags.insert_reserved(key,*flag,grant).map_err(|(error,_,_)|error)?;self.operation+=1;self.phase=5;Ok(p(d))}else{let d=RetirementDemand{copy_bytes:2*size_of::<usize>(),depth:1,..Default::default()};if !permits(grant,d){return Ok(Default::default())}self.operation+=1;self.phase=5;Ok(p(d))}},
   _=>{let d=RetirementDemand{copy_bytes:size_of::<NativeEditDigest>()+size_of::<NativeEffectiveDigest>()+4*size_of::<usize>(),depth:1,..Default::default()};if !permits(grant,d){return Ok(Default::default())}self.digest=Default::default();self.effective=Default::default();self.source=None;self.ordinal+=1;self.operation=0;self.phase=0;Ok(p(d))}
  }
 }
 /// 🤝️ Moves the same prepared cursor and revision roots; displaced publication owners return to these slots for paid closure.
 pub fn swap_prepared(&mut self,cursor:&mut HistoryPageStack<String>,revision:&mut CursorRevisionAccumulator)->Result<(),ValueError>{if !self.prepared(){return Err(invalid("replay metadata is not prepared"))}std::mem::swap(self.cursor.as_mut().unwrap(),cursor);std::mem::swap(self.revision.as_mut().unwrap(),revision);self.closing=true;Ok(())}
 /// 🛑️ Cancellation retains every original private or displaced metadata allocation.
 pub fn begin_close(&mut self){self.closing=true;}
 /// 📏️ Quotes one actual original metadata child or its exact close frame.
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.cursor.is_some(){return self.retirement.next_owner_demands::<HistoryPageStack<String>>(true,&None,body)}if self.revision.is_some(){return self.retirement.next_owner_demands::<CursorRevisionAccumulator>(true,&None,body)}Ok(RetirementDemand{copy_bytes:size_of::<Self>(),depth:1,..Default::default()})}
 /// ♻️ Physically closes private or displaced metadata without moving the visible Store roots.
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.begin_close();if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(grant.maximum_copy_bytes)?;if !permits(grant,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.retirement.is_empty(){return self.retirement.step_granted(grant)}if self.cursor.is_some(){return Ok(self.retirement.begin_granted(&mut self.cursor,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.revision.is_some(){return Ok(self.retirement.begin_granted(&mut self.revision,grant)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}self.source=None;self.finished=false;Ok(RetainedCloneStep::Progress(p(d)))}
 /// 🫙️ Terminal ownership includes both private roots and all typed retirement frames.
 pub fn terminal_is_empty(&self)->bool{self.revision.is_none()&&self.cursor.is_none()&&self.retirement.is_empty()&&self.source.is_none()}
}
impl Drop for OriginalReplayMetadata{fn drop(&mut self){assert!(self.terminal_is_empty()||std::thread::panicking(),"replay metadata must publish or retire its exact original roots");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.revision);ManuallyDrop::drop(&mut self.cursor);}}}}

